SELECT pg_backend_pid();
SELECT pin.build_revision();
SHOW ALL;
SET pin.enable_packed_postings=off;
SET pin.enable_grouped_storage=on;
SET pin.enable_direct_tid_segments=off;
SET pin.enable_count_fastpath=off;
SET pin.enable_grouped_count=off;
SET pin.enable_grouped_scan=on;
SET enable_seqscan=off;
SET enable_indexscan=off;
SHOW data_directory;
CREATE TABLE pin_direct_build_off(id integer PRIMARY KEY, body text) WITH (autovacuum_enabled=false);
INSERT INTO pin_direct_build_off SELECT i, 'echo word' || lpad((((i-1)%2000)+1)::text,5,'0') FROM generate_series(1,16000) i;
SET pin.enable_direct_tid_build=off;
SELECT pg_current_wal_insert_lsn();
CREATE INDEX pin_direct_build_off_pin ON pin_direct_build_off USING pin(body);
SELECT pg_current_wal_insert_lsn();
ANALYZE pin_direct_build_off;
CHECKPOINT;
SELECT pg_relation_size('pin_direct_build_off_pin');
SELECT pg_relation_filepath('pin_direct_build_off_pin');
CREATE TABLE pin_direct_build_on(id integer PRIMARY KEY, body text) WITH (autovacuum_enabled=false);
INSERT INTO pin_direct_build_on SELECT i, 'echo word' || lpad((((i-1)%2000)+1)::text,5,'0') FROM generate_series(1,16000) i;
SET pin.enable_direct_tid_build=on;
SELECT pg_current_wal_insert_lsn();
CREATE INDEX pin_direct_build_on_pin ON pin_direct_build_on USING pin(body);
SELECT pg_current_wal_insert_lsn();
ANALYZE pin_direct_build_on;
CHECKPOINT;
SELECT pg_relation_size('pin_direct_build_on_pin');
SELECT pg_relation_filepath('pin_direct_build_on_pin');
CREATE TABLE pin_direct_build_gin(id integer PRIMARY KEY, body text, search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple',body)) STORED) WITH (autovacuum_enabled=false);
INSERT INTO pin_direct_build_gin(id,body) SELECT i, 'echo word' || lpad((((i-1)%2000)+1)::text,5,'0') FROM generate_series(1,16000) i;
CREATE INDEX pin_direct_build_gin_idx ON pin_direct_build_gin USING gin(search_vector);
ANALYZE pin_direct_build_gin;
SELECT pg_relation_size('pin_direct_build_gin_idx');
EXPLAIN (ANALYZE,BUFFERS,TIMING OFF,FORMAT JSON) SELECT count(*) FROM pin_direct_build_off WHERE body OPERATOR(pin.@@@) pin.parse_query('echo');
SELECT id FROM pin_direct_build_off WHERE body OPERATOR(pin.@@@) pin.parse_query('echo') ORDER BY id;
SET enable_seqscan=on;
SET enable_bitmapscan=off;
SELECT id FROM pin_direct_build_off WHERE body OPERATOR(pin.@@@) pin.parse_query('echo') ORDER BY id;
SET enable_seqscan=off;
SET enable_bitmapscan=on;
EXPLAIN (ANALYZE,BUFFERS,TIMING OFF,FORMAT JSON) SELECT count(*) FROM pin_direct_build_on WHERE body OPERATOR(pin.@@@) pin.parse_query('echo');
SELECT id FROM pin_direct_build_on WHERE body OPERATOR(pin.@@@) pin.parse_query('echo') ORDER BY id;
SET enable_seqscan=on;
SET enable_bitmapscan=off;
SELECT id FROM pin_direct_build_on WHERE body OPERATOR(pin.@@@) pin.parse_query('echo') ORDER BY id;
SET enable_seqscan=off;
SET enable_bitmapscan=on;
EXPLAIN (ANALYZE,BUFFERS,TIMING OFF,FORMAT JSON) SELECT count(*) FROM pin_direct_build_gin WHERE search_vector @@ to_tsquery('simple','echo');
SELECT id FROM pin_direct_build_gin WHERE search_vector @@ to_tsquery('simple','echo') ORDER BY id;
SET enable_seqscan=on;
SET enable_bitmapscan=off;
SELECT id FROM pin_direct_build_gin WHERE search_vector @@ to_tsquery('simple','echo') ORDER BY id;
SET enable_seqscan=off;
SET enable_bitmapscan=on;
